private lemma mem_insertHornerGroupDesc {n : ℕ} {S : Type*}
    (group x : HornerGroup n S) :
    ∀ groups, x ∈ insertHornerGroupDesc group groups ↔ x = group ∨ x ∈ groups

private lemma sortHornerGroups_descending {n : ℕ} {S : Type*}
    (groups : List (HornerGroup n S)) :
    descendingByExponent (sortHornerGroups groups)

private lemma hornerGroups_descending {n : ℕ} {S : Type*}
    (k : ℕ) (terms : List (HornerTerm n S)) :
    descendingByExponent (hornerGroups k terms)

private lemma descendingByExponent_map {α β : Type*} (f : α → β) :
    ∀ groups : List (ℕ × α), descendingByExponent groups →
      descendingByExponent (groups.map fun group ↦ (group.1, f group.2))

lemma coeff_restrictTotalDegree_eq_self_of_le {d : ℕ} {m : CMvMonomial n}
    {p : CMvPolynomial n R} (h : m.totalDegree ≤ d) :
    (CMvPolynomial.restrictTotalDegree d p).coeff m = p.coeff m

lemma coeff_restrictTotalDegree_eq_zero_of_lt {d : ℕ} {m : CMvMonomial n}
    {p : CMvPolynomial n R} (h : d < m.totalDegree) :
    (CMvPolynomial.restrictTotalDegree d p).coeff m = 0

lemma coeff_restrictDegree_eq_self_of_le {d : ℕ} {m : CMvMonomial n}
    {p : CMvPolynomial n R} (h : ∀ i : Fin n, m.degreeOf i ≤ d) :
    (CMvPolynomial.restrictDegree d p).coeff m = p.coeff m

lemma coeff_restrictDegree_eq_zero_of_not_le {d : ℕ} {m : CMvMonomial n}
    {p : CMvPolynomial n R} (h : ¬ (∀ i : Fin n, m.degreeOf i ≤ d)) :
    (CMvPolynomial.restrictDegree d p).coeff m = 0

lemma totalDegree_le_of_mem_monomials_restrictTotalDegree {d : ℕ} {m : CMvMonomial n}
    {p : CMvPolynomial n R}
    (hm : m ∈ Lawful.monomials (CMvPolynomial.restrictTotalDegree d p)) :
    m.totalDegree ≤ d

lemma degreeOf_le_of_mem_monomials_restrictDegree {d : ℕ} {m : CMvMonomial n}
    {p : CMvPolynomial n R}
    (hm : m ∈ Lawful.monomials (CMvPolynomial.restrictDegree d p)) :
    ∀ i : Fin n, m.degreeOf i ≤ d

@[simp] lemma leadingCoeff_eq_zero_of_leadingMonomial_eq_none
    {n : ℕ} {R : Type*} [Zero R] [MonomialOrder n] {p : CMvPolynomial n R}
    (h : leadingMonomial p = none) : leadingCoeff p = 0

lemma leadingCoeff_eq_coeff_of_leadingMonomial_eq_some
    {n : ℕ} {R : Type*} [Zero R] [MonomialOrder n] {p : CMvPolynomial n R}
    {m : CMvMonomial n} (h : leadingMonomial p = some m) : leadingCoeff p = coeff m p

lemma toFinsupp_unitMono {k : ℕ}
    (i : Fin k) :
    CMvMonomial.toFinsupp
      (Vector.ofFn (fun j : Fin k =>
        if j = i then 1 else 0)) =
    Finsupp.single i 1

@[grind←]
protected lemma grind_fromUnlawful_congr {p₁ p₂ : Unlawful n R}
    (h : p₁ = p₂) : Lawful.fromUnlawful p₁ = Lawful.fromUnlawful p₂

@[ext, grind ext]
lemma ext_getElem? {n R} {t₁ t₂ : Unlawful n R}
    (h : ∀ (k : CMvMonomial n), t₁[k]? = t₂[k]?) : t₁ = t₂

private lemma popCount_pos' {m : ℕ} (hm : 0 < m) :
    Nat.popCount m =
      m % 2 + Nat.popCount (m / 2)

private lemma testBit_eq_of_getBit_eq {m n k : ℕ}
    (h : Nat.getBit k m = Nat.getBit k n) :
    m.testBit k = n.testBit k

private lemma testBit_sub_self {m k : ℕ}
    (hbit : m.testBit k = true) :
    (m - 2 ^ k).testBit k = false

private lemma testBit_sub_ne {m k l : ℕ}
    (hbit : m.testBit k = true) (hl : l ≠ k) :
    (m - 2 ^ k).testBit l = m.testBit l

private lemma div_mod2_of_testBit_true {m k : ℕ}
    (h : m.testBit k = true) :
    (m / 2 ^ k) % 2 = 1

private lemma div_mod2_of_testBit_false {m k : ℕ}
    (h : m.testBit k = false) :
    (m / 2 ^ k) % 2 = 0

private lemma rewrite_odd (m d : ℕ)
    (hodd : (m / d) % 2 = 1) :
    m = d * 2 * (m / d / 2) + (d + m % d)

private lemma rewrite_even (m d : ℕ)
    (heven : (m / d) % 2 = 0) :
    m = d * 2 * (m / d / 2) + m % d

private lemma mod_double_of_odd_div (m d : ℕ)
    (hd : 0 < d) (hodd : (m / d) % 2 = 1) :
    m % (d * 2) = d + m % d

private lemma mod_double_of_even_div (m d : ℕ)
    (hd : 0 < d) (heven : (m / d) % 2 = 0) :
    m % (d * 2) = m % d

private lemma mod_ne_lift {m n k : ℕ}
    (h : m % 2 ^ k ≠ n % 2 ^ k) :
    m % 2 ^ (k + 1) ≠ n % 2 ^ (k + 1)

private lemma popCount_le_of_and_eq :
    ∀ {m n : ℕ}, m &&& n = n →
      n.popCount ≤ m.popCount

private lemma div_pow_succ_eq_of_both_false {m n k : ℕ}
    (hm : m.testBit k = false) (hn : n.testBit k = false) :
    m / 2 ^ k = n / 2 ^ k ↔ m / 2 ^ (k + 1) = n / 2 ^ (k + 1)

private lemma div_pow_succ_eq_of_both_true {m n k : ℕ}
    (hm : m.testBit k = true) (hn : n.testBit k = true) :
    m / 2 ^ k = n / 2 ^ k ↔ m / 2 ^ (k + 1) = n / 2 ^ (k + 1)

private lemma div_pow_ne_of_diff {m n k : ℕ}
    (hm : m.testBit k = true) (hn : n.testBit k = false) :
    m / 2 ^ k ≠ n / 2 ^ k

private lemma div_pow_succ_sub_of_testBit_true {m k : ℕ}
    (hbit : m.testBit k = true) :
    (m - 2 ^ k) / 2 ^ (k + 1) = m / 2 ^ (k + 1)

private lemma monomial_basis_even {n : ℕ} (x : Vector R (n + 1)) (j : Fin (2 ^ n)) :
    (monomialBasis x).get ⟨2 * j.val, by omega⟩ =
    (monomialBasis x.tail).get j

private lemma monomial_basis_odd {n : ℕ} (x : Vector R (n + 1)) (j : Fin (2 ^ n)) :
    (monomialBasis x).get ⟨2 * j.val + 1, by omega⟩ =
    x.head * (monomialBasis x.tail).get j

private lemma lagrange_basis_even {n : ℕ} (x : Vector R (n + 1)) (j : Fin (2 ^ n)) :
    (lagrangeBasis x).get ⟨2 * j.val, by omega⟩ =
    (1 - x.head) * (lagrangeBasis x.tail).get j

private lemma lagrange_basis_odd {n : ℕ} (x : Vector R (n + 1)) (j : Fin (2 ^ n)) :
    (lagrangeBasis x).get ⟨2 * j.val + 1, by omega⟩ =
    x.head * (lagrangeBasis x.tail).get j

private lemma toPoly_reverse_coeff (n : Nat) (p : Raw R) (i : Nat) :
    (reverse n p).toPoly.coeff i =
      if i < n then p.toPoly.coeff (n - 1 - i) else 0

private lemma toPoly_mulLow_lowEq (M : MulLowContext R) (k : Nat)
    (p q : Raw R) :
    lowEq k (M.mulLow k p q).toPoly (p.toPoly * q.toPoly)

private lemma lowEq.add {k : Nat} {p₁ p₂ q₁ q₂ : R[X]}
    (h₁ : lowEq k p₁ q₁) (h₂ : lowEq k p₂ q₂) :
    lowEq k (p₁ + p₂) (q₁ + q₂)

private lemma lowEq.sub {k : Nat} {p₁ p₂ q₁ q₂ : R[X]}
    (h₁ : lowEq k p₁ q₁) (h₂ : lowEq k p₂ q₂) :
    lowEq k (p₁ - p₂) (q₁ - q₂)

private lemma min_mul_two_pow_le_min_min_mul (k n fuel : Nat) :
    Nat.min k (n * 2 ^ (fuel + 1)) ≤
      Nat.min k (Nat.min k (2 * n) * 2 ^ fuel)

private lemma inverseModX_base_lowEq (p : Raw R)
    (h0 : p.toPoly.coeff 0 ≠ 0) :
    lowEq 1 (p.toPoly * (Raw.C (p.coeff 0)⁻¹).toPoly) 1

private lemma inverseModX_lowEq (M : MulLowContext R) (k : Nat)
    (p : Raw R) (h0 : p.toPoly.coeff 0 ≠ 0) :
    lowEq k (p.toPoly * (inverseModX M k p).toPoly) 1

private lemma toPoly_reverse_eq_reflect (n : Nat) (p : Raw R)
    (hdeg : p.toPoly.natDegree < n) :
    (reverse n p).toPoly = Polynomial.reflect (n - 1) p.toPoly

private lemma toPoly_mulLow_natDegree_le (M : MulLowContext R) (k : Nat)
    (p q : Raw R) :
    (M.mulLow k p q).toPoly.natDegree ≤ k - 1

private lemma raw_toPoly_natDegree_lt_size_of_trim_eq (p : Raw R)
    (htrim : p.trim = p) (hpos : 0 < p.size) :
    p.toPoly.natDegree < p.size

private lemma raw_coeff_last_eq_leadingCoeff_of_trim_eq (q : Raw R)
    (htrim : q.trim = q) (hpos : 0 < q.size) :
    q.coeff (q.size - 1) = q.leadingCoeff

lemma encode_get [Semiring F] [BEq F] [LawfulBEq F] (D : Domain F) {k : ℕ}
    (msg : Vector F k) (i : Fin D.n) :
