theorem gsCore_complete_of_roots_all_valid_witnesses {F : Type*}
    [Field F] [BEq F] [LawfulBEq F] [DecidableEq F]
    {points : Array (Prod F F)}
    {interpContext : GSInterpContext F} {rootContext : GSRootContext F}
