private theorem eval_composeY_eq_zero_of_matched_point {F : Type*}
    [Field F] [BEq F] [LawfulBEq F] [DecidableEq F]
    {points : Array (F × F)} {params : GSInterpParams}
    {Q : CBivariate F} {p : CPolynomial F} {point : F × F}
