private lemma array_foldl_push_toList {α : Type*} (xs acc : Array α) :
    (Array.foldl (fun acc x ↦ acc.push x) acc xs 0 xs.size).toList =
      acc.toList ++ xs.toList

private lemma vector_array_foldl_push_toList (p : CMlPolynomialEval R n) (acc : Array R) :
    (Array.foldl (fun acc x ↦ acc.push x) acc p.toArray 0 (2 ^ n)).toList =
      acc.toList ++ p.toArray.toList

private lemma valuesByPolynomial_toList (polys : Array (CMlPolynomialEval R n)) :
    (valuesByPolynomial polys).toList =
      polys.toList.flatMap (fun p ↦ p.toArray.toList)

private lemma List.flatMap_map {α β γ : Type*} (xs : List α) (f : α → β)
    (g : β → List γ) :
    (xs.map f).flatMap g = xs.flatMap (fun x ↦ g (f x))

theorem exists_factor_natDegree_le_of_reducible (P : R[X]) {n : ℕ}
    (h_deg : P.natDegree = n) (h_pos : 0 < n) (h_red : ¬ Irreducible P) :
    ∃ q, Irreducible q ∧ q ∣ P ∧ q.natDegree ≤ n / 2

theorem weight_le_natWeightedDegree_of_lt_natDegree_succ {u v n : ℕ}
    (hn : n < f.natDegree.succ) :
    u * (f.coeff n).natDegree + v * n ≤ natWeightedDegree f u v
